import{_ as p,a0 as o,w as d,s as r,I as t,a1 as e,A as n,x as a,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Debian 10（Buster）安裝後要做的前 8 件事 | LCTT x X-CMD","titleTemplate":false,"description":"Debian 10（Buster）安裝後要做的前 8 件事 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Debian 10（Buster）安裝後要做的前 8 件事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Debian 10（Buster）安裝後要做的前 8 件事 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190729 Top 8 Things to do after Installing Debian 10 (Buster)","title":"Debian 10（Buster）安裝後要做的前 8 件事","tag":"201908","desc":""},"relativePath":"201908/20190729 Top 8 Things to do after Installing Debian 10 (Buster).md","filePath":"[post].md"}'),h={name:"201908/20190729 Top 8 Things to do after Installing Debian 10 (Buster).md"};function u(g,s,c,b,k,f){const i=o("Link");return d(),r("div",null,[t("p",null,[e(i,{href:"collector:",title:"lujun9972"},{default:n(()=>[...s[0]||(s[0]=[a("#",-1)])]),_:1}),s[5]||(s[5]=a(": subject: (Top 8 Things to do after Installing Debian 10 (Buster)) ",-1)),e(i,{href:"collector:",title:"lujun9972"},{default:n(()=>[...s[1]||(s[1]=[a("#",-1)])]),_:1}),s[6]||(s[6]=a(": via: (",-1)),e(i,{href:"https://www.linuxtechi.com/things-to-do-after-installing-debian-10/"},{default:n(()=>[...s[2]||(s[2]=[a("https://www.linuxtechi.com/things-to-do-after-installing-debian-10/",-1)])]),_:1}),s[7]||(s[7]=a(") ",-1)),e(i,{href:"collector:",title:"lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("#",-1)])]),_:1}),s[8]||(s[8]=a(": author: (Pradeep Kumar ",-1)),e(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...s[4]||(s[4]=[a("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),s[9]||(s[9]=a(")",-1))]),s[31]||(s[31]=t("h1",{id:"debian-10-buster-安裝後要做的前-8-件事",tabindex:"-1"},[a("Debian 10（Buster）安裝後要做的前 8 件事 "),t("a",{class:"header-anchor",href:"#debian-10-buster-安裝後要做的前-8-件事","aria-label":"Permalink to “Debian 10（Buster）安裝後要做的前 8 件事”"},"​")],-1)),t("p",null,[s[11]||(s[11]=a("Debian 10 的代號是 Buster，它是來自 Debian 家族的最新 LTS 發佈版本，並包含大量的特色功能。因此，如果你已經在你的電腦上安裝了 Debian 10，並在思考接下來該做什麼，那麼，請繼續閲讀這篇文章直到結尾，因為我們為你提供在安裝 Debian 10 後要做的前 8 件事。對於還沒有安裝 Debian 10 的人們，請閲讀這篇指南 ",-1)),e(i,{href:"https://linux.cn/article-11083-1.html"},{default:n(()=>[...s[10]||(s[10]=[a("圖解 Debian 10 (Buster) 安裝步驟",-1)])]),_:1}),s[12]||(s[12]=a("。 讓我們繼續這篇文章。",-1))]),s[32]||(s[32]=l(`<p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Things-to-do-after-installing-debian10.jpg" alt=""></p><h3 id="_1-安裝和配置-sudo" tabindex="-1">1) 安裝和配置 sudo <a class="header-anchor" href="#_1-安裝和配置-sudo" aria-label="Permalink to “1) 安裝和配置 sudo”">​</a></h3><p>在設置完成 Debian 10 後，你需要做的第一件事是安裝 sudo 軟件包，因為它能夠使你獲得管理員權限來安裝你需要的軟件包。為安裝和配置 sudo，請使用下面的命令：</p><p>變成 root 用户，然後使用下面的命令安裝 sudo 軟件包，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ su -</span></span>
<span class="line"><span>Password:</span></span>
<span class="line"><span>root@linuxtechi:~# apt install sudo -y</span></span></code></pre></div>`,5)),t("p",null,[s[14]||(s[14]=a("添加你的本地用户到 sudo 組，使用下面的 ",-1)),e(i,{href:"https://www.linuxtechi.com/linux-commands-to-manage-local-accounts/"},{default:n(()=>[...s[13]||(s[13]=[a("usermod",-1)])]),_:1}),s[15]||(s[15]=a(" 命令，",-1))]),s[33]||(s[33]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# usermod -aG sudo pkumar</span></span>
<span class="line"><span>root@linuxtechi:~#</span></span></code></pre></div><p>現在驗證是否本地用户獲得 sudo 權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ id</span></span>
<span class="line"><span>uid=1000(pkumar) gid=1000(pkumar) groups=1000(pkumar),27(sudo)</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo vi /etc/hosts</span></span>
<span class="line"><span>[sudo] password for pkumar:</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><h3 id="_2-校正日期和時間" tabindex="-1">2) 校正日期和時間 <a class="header-anchor" href="#_2-校正日期和時間" aria-label="Permalink to “2) 校正日期和時間”">​</a></h3><p>在你成功配置 sudo 軟件包後，接下來，你需要根據你的位置來校正日期和時間。為了校正日期和時間，</p><p>轉到系統 <strong>設置</strong> –&gt; <strong>詳細説明</strong> –&gt; <strong>日期和時間</strong> ，然後更改為適合你的位置的時區。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Adjust-date-time-Debian10.jpg" alt=""></p><p>一旦時區被更改，你可以看到時鐘中的時間自動更改。</p><h3 id="_3-應用所有更新" tabindex="-1">3) 應用所有更新 <a class="header-anchor" href="#_3-應用所有更新" aria-label="Permalink to “3) 應用所有更新”">​</a></h3><p>在 Debian 10 安裝後，建議安裝所有 Debian 10 軟件包存儲庫中可用的更新，執行下面的 <code>apt</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo apt upgrade -y</span></span></code></pre></div><p><strong>注意：</strong> 如果你是 vi 編輯器的忠實粉絲，那麼使用下面的 <code>apt</code> 命令安裝 <code>vim</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install vim -y</span></span></code></pre></div><h3 id="_4-安裝-flash-播放器插件" tabindex="-1">4) 安裝 Flash 播放器插件 <a class="header-anchor" href="#_4-安裝-flash-播放器插件" aria-label="Permalink to “4) 安裝 Flash 播放器插件”">​</a></h3><p>默認情況下，Debian 10（Buster）存儲庫不包含 Flash 插件，因此，用户需要遵循下面的介紹來在他們的系統中查找和安裝 flash 播放器。</p><p>為 Flash 播放器配置存儲庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ echo &quot;deb http://ftp.de.debian.org/debian buster main contrib&quot; | sudo tee -a  /etc/apt/sources.list</span></span>
<span class="line"><span>deb http://ftp.de.debian.org/debian buster main contrib</span></span>
<span class="line"><span>root@linuxtechi:~</span></span></code></pre></div><p>現在使用下面的命令更新軟件包索引：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span></code></pre></div><p>使用下面的 <code>apt</code> 命令安裝 Flash 插件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install pepperflashplugin-nonfree -y</span></span></code></pre></div><p>一旦軟件包被成功安裝，接下來，嘗試播放 YouTube 中的視頻：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Flash-Player-plugin-Debian10.jpg" alt=""></p><h3 id="_5-安裝軟件-如-vlc、skype、filezilla-和截圖工具" tabindex="-1">5) 安裝軟件，如 VLC、Skype、FileZilla 和截圖工具 <a class="header-anchor" href="#_5-安裝軟件-如-vlc、skype、filezilla-和截圖工具" aria-label="Permalink to “5) 安裝軟件，如 VLC、Skype、FileZilla 和截圖工具”">​</a></h3><p>如此，現在我們已經啓用 Flash 播放器，是時候在我們的 Debian 10 系統中安裝所有其它的軟件，如 VLC、Skype，Filezilla 和截圖工具（flameshot）。</p><h4 id="安裝-vlc-多媒體播放器" tabindex="-1">安裝 VLC 多媒體播放器 <a class="header-anchor" href="#安裝-vlc-多媒體播放器" aria-label="Permalink to “安裝 VLC 多媒體播放器”">​</a></h4><p>為在你的系統中安裝 VLC 播放器，使用下面的 <code>apt</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install vlc -y</span></span></code></pre></div><p>在成功安裝 VLC 播放器後，嘗試播放你喜歡的視頻。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Debian10-VLC.jpg" alt=""></p><h4 id="安裝-skype" tabindex="-1">安裝 Skype <a class="header-anchor" href="#安裝-skype" aria-label="Permalink to “安裝 Skype”">​</a></h4><p>首先，下載最新的 Skype 軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ wget https://go.skype.com/skypeforlinux-64.deb</span></span></code></pre></div><p>接下來，使用 <code>apt</code> 命令安裝軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install ./skypeforlinux-64.deb</span></span></code></pre></div><p>在成功安裝 Skype 後，嘗試訪問它，並輸入你的用户名和密碼。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/skype-Debian10.jpg" alt=""></p><h4 id="安裝-filezilla" tabindex="-1">安裝 Filezilla <a class="header-anchor" href="#安裝-filezilla" aria-label="Permalink to “安裝 Filezilla”">​</a></h4><p>為在你的系統中安裝 Filezilla，使用下面的 <code>apt</code> 命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install filezilla -y</span></span></code></pre></div><p>一旦 FileZilla 軟件包被成功安裝，嘗試訪問它。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/FileZilla-Debian10.jpg" alt=""></p><h4 id="安裝截圖工具-flameshot" tabindex="-1">安裝截圖工具（flameshot） <a class="header-anchor" href="#安裝截圖工具-flameshot" aria-label="Permalink to “安裝截圖工具（flameshot）”">​</a></h4><p>使用下面的命令來安裝截圖工具：flameshot，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install flameshot -y</span></span></code></pre></div><p><strong>注意：</strong> Shutter 工具在 Debian 10 中已被移除。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/flameshoot-debian10.jpg" alt=""></p><h3 id="_6-啓用和啓動防火牆" tabindex="-1">6) 啓用和啓動防火牆 <a class="header-anchor" href="#_6-啓用和啓動防火牆" aria-label="Permalink to “6) 啓用和啓動防火牆”">​</a></h3><p>總是建議啓動防火牆來使你的網絡安全。如果你希望在 Debian 10 中啓用防火牆， <strong>UFW</strong>（簡單的防火牆）是最好的控制防火牆的工具。UFW 在 Debian 存儲庫中可用，它非常容易安裝，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install ufw</span></span></code></pre></div><p>在你安裝 UFW 後，接下來的步驟是設置防火牆。因此，設置防火牆，通過拒絕端口來禁用所有的傳入流量，並且只允許需要的端口傳出，像 ssh、http 和 https。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ufw default deny incoming</span></span>
<span class="line"><span>Default incoming policy changed to &#39;deny&#39;</span></span>
<span class="line"><span>(be sure to update your rules accordingly)</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo ufw default allow outgoing</span></span>
<span class="line"><span>Default outgoing policy changed to &#39;allow&#39;</span></span>
<span class="line"><span>(be sure to update your rules accordingly)</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>允許 SSH 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ufw allow ssh</span></span>
<span class="line"><span>Rules updated</span></span>
<span class="line"><span>Rules updated (v6)</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>假使你在系統中已經安裝 Web 服務器，那麼使用下面的 <code>ufw</code> 命令來在防火牆中允許它們的端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ufw allow 80</span></span>
<span class="line"><span>Rules updated</span></span>
<span class="line"><span>Rules updated (v6)</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo ufw allow 443</span></span>
<span class="line"><span>Rules updated</span></span>
<span class="line"><span>Rules updated (v6)</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>最後，你可以使用下面的命令啓用 UFW：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ufw enable</span></span>
<span class="line"><span>Command may disrupt existing ssh connections. Proceed with operation (y|n)? y</span></span>
<span class="line"><span>Firewall is active and enabled on system startup</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>假使你想檢查你的防火牆的狀態，你可以使用下面的命令檢查它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ufw status</span></span></code></pre></div><h3 id="_7-安裝虛擬化軟件-virtualbox" tabindex="-1">7) 安裝虛擬化軟件（VirtualBox） <a class="header-anchor" href="#_7-安裝虛擬化軟件-virtualbox" aria-label="Permalink to “7) 安裝虛擬化軟件（VirtualBox）”">​</a></h3><p>安裝 Virtualbox 的第一步是將 Oracle VirtualBox 存儲庫的公鑰導入到你的 Debian 10 系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ wget -q https://www.virtualbox.org/download/oracle_vbox_2016.asc -O- | sudo apt-key add -</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span>root@linuxtechi:~$ wget -q https://www.virtualbox.org/download/oracle_vbox.asc -O- | sudo apt-key add -</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>如果導入成功，你將看到一個 “OK” 顯示信息。</p><p>接下來，你需要添加存儲庫到倉庫列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo add-apt-repository &quot;deb http://download.virtualbox.org/virtualbox/debian buster contrib&quot;</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>最後，是時候在你的系統中安裝 VirtualBox 6.0：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo apt install virtualbox-6.0 -y</span></span></code></pre></div><p>一旦 VirtualBox 軟件包被成功安裝，嘗試訪問它，並開始創建虛擬機。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/VirtualBox6-Debian10-Workstation.jpg" alt=""></p><h3 id="_8-安裝最新的-amd-驅動程序" tabindex="-1">8) 安裝最新的 AMD 驅動程序 <a class="header-anchor" href="#_8-安裝最新的-amd-驅動程序" aria-label="Permalink to “8) 安裝最新的 AMD 驅動程序”">​</a></h3><p>最後，你也可以安裝需要的附加 AMD 顯卡驅動程序（如 ATI 專有驅動）和 Nvidia 圖形驅動程序。為安裝最新的 AMD 驅動程序，首先，我們需要修改 <code>/etc/apt/sources.list</code> 文件，在包含 <strong>main</strong> 和 <strong>contrib</strong> 的行中添加 <strong>non-free</strong> 單詞，示例如下顯示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo vi /etc/apt/sources.list</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>deb http://deb.debian.org/debian/ buster main non-free contrib</span></span>
<span class="line"><span>deb-src http://deb.debian.org/debian/ buster main non-free contrib</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deb http://security.debian.org/debian-security buster/updates main contrib non-free</span></span>
<span class="line"><span>deb-src http://security.debian.org/debian-security buster/updates main contrib non-free</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deb http://ftp.us.debian.org/debian/ buster-updates main contrib non-free</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>現在，使用下面的 <code>apt</code> 命令來在 Debian 10 系統中安裝最新的 AMD 驅動程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo apt install firmware-linux firmware-linux-nonfree libdrm-amdgpu1 xserver-xorg-video-amdgpu -y</span></span></code></pre></div><p>這就是這篇文章的全部內容，我希望你瞭解在安裝 Debian 10 後應該做什麼。請在下面的評論區，分享你的反饋和評論。</p><hr>`,78)),t("p",null,[s[17]||(s[17]=a("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/things-to-do-after-installing-debian-10/"},{default:n(()=>[...s[16]||(s[16]=[a("https://www.linuxtechi.com/things-to-do-after-installing-debian-10/",-1)])]),_:1})]),t("p",null,[s[22]||(s[22]=a("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...s[18]||(s[18]=[a("Pradeep Kumar",-1)])]),_:1}),s[23]||(s[23]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[19]||(s[19]=[a("lujun9972",-1)])]),_:1}),s[24]||(s[24]=a(" 譯者：",-1)),e(i,{href:"https://github.com/robsean"},{default:n(()=>[...s[20]||(s[20]=[a("robsean",-1)])]),_:1}),s[25]||(s[25]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[21]||(s[21]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[28]||(s[28]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[26]||(s[26]=[a("LCTT",-1)])]),_:1}),s[29]||(s[29]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[27]||(s[27]=[a("Linux中國",-1)])]),_:1}),s[30]||(s[30]=a(" 榮譽推出",-1))])])}const w=p(h,[["render",u]]);export{y as __pageData,w as default};
